 experience:[['title','经历名称'],['category','类别','select',{project:'项目',work:'工作',research:'研究',publication:'论文',skill:'技能',award:'获奖'}],['organization','单位／团队'],['role','本人角色'],['start_date','开始年月'],['end_date','结束年月'],['description','内容与个人贡献','textarea']],
