if(typeof CareerForms!=='undefined')CareerForms.configure({api,accountContext,ensureAccount,esc,notify,getState:()=>state,isActive:()=>page==='forms'});
function accountContext(){return {userId:state.user_id||state.account?.id||null,epoch:accountEpoch};}
function ensureAccount(context){if(context.epoch!==accountEpoch){const error=Error('账号已切换，旧账号的操作结果已丢弃。');error.code='stale_account';throw error;}}
function staleAccount(error){return error.code==='stale_account';}
async function api(operation,args={},context=accountContext()){
 ensureAccount(context);
 if(accountSwitching&&!['account.select','account.create'].includes(operation)){const error=Error('正在切换账号，请稍后操作。');error.code='stale_account';throw error;}
 const isState=operation==='state',url=isState?'/api/state'+(context.userId?'?user_id='+encodeURIComponent(context.userId):''):'/api/action';
 const opts=isState?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,args,user_id:context.userId})};
 let res,obj;try{res=await fetch(url,opts);try{obj=await res.json()}catch{throw Error('本地服务返回异常，请确认服务正在运行。')}}catch(error){ensureAccount(context);throw error;}
 ensureAccount(context);
 if(!res.ok||!obj.ok){const error=Error(obj.error?.message||'操作未完成');error.code=obj.error?.code;throw error;}return obj.data;
}
function notify(message,error=false){if(error){$('#notice').textContent=message;$('#notice').hidden=false}else{$('#notice').hidden=true;$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}}
async function load(recoverAccount=true){
 if(accountSwitching)return false;
 const version=++loadVersion,context=accountContext();
 try{
  const nextState=await api('state',{},context),nextContext={...context,userId:nextState.user_id||nextState.account?.id||context.userId};
  if(version!==loadVersion)return false;
  const initial=nextState.records?.application||[],storedExpected=nextState.counts?.application,suppressed=nextState.recommendation_activity?.suppressed_recommendations??nextState.recommendation_activity?.suppressed_candidates;
  const expected=Number.isInteger(storedExpected)&&Number.isInteger(suppressed)&&suppressed>=0&&suppressed<=storedExpected?storedExpected-suppressed:storedExpected;
  const nextCoverage={complete:true,expected:Number.isInteger(expected)?expected:initial.length};
  if(Number.isInteger(expected)&&expected>initial.length){
   const collected=[...initial],ids=new Set(initial.map(r=>r.id));
   try{
    for(let offset=initial.length;offset<expected;){
     const result=await api('record.list',{kind:'application',limit:200,offset},nextContext);
     if(version!==loadVersion)return false;
     if(result.total!==expected||!Array.isArray(result.items)||!result.items.length||new Set(result.items.map(r=>r.id)).size!==result.items.length||result.items.some(r=>r.kind!=='application'||ids.has(r.id)))throw Error('记录在读取时发生变化');
     for(const record of result.items){ids.add(record.id);collected.push(record)}
     offset+=result.items.length;
    }
    if(collected.length!==expected)throw Error('记录数量不一致');
   }catch(error){if(staleAccount(error))throw error;nextCoverage.complete=false;}
   nextState.records.application=collected;
  }
  let nextResources=resources;
  if(['resources','intention','resumes'].includes(page))nextResources=(await api('resource.list',{},nextContext)).items||[];
  if(page==='forms'&&typeof CareerForms!=='undefined')await CareerForms.load(nextContext);
  let nextProfile=profileRead,nextRelations=profileRelations;
  if(['profile','intention','resumes'].includes(page)){
   profileCatalog=profileCatalog||await api('profile.schema',{},nextContext);
   for(const [kind,definition] of Object.entries(profileCatalog.records))fields[kind]=definition.fields.map(f=>[f.key,f.label,f.type,f.options]);
  }
  if(page==='profile'||page==='resumes'){
   const first=await api('profile.get',{limit:100},nextContext),items=[...first.items];let offset=first.next_offset;
   while(offset!==null){const part=await api('profile.get',{limit:100,offset},nextContext);if(part.total!==first.total||!part.items.length)throw Error('资料在分页读取时发生变化，请刷新。');items.push(...part.items);offset=part.next_offset;}
   if(new Set(items.map(r=>r.id)).size!==first.total)throw Error('资料分页不完整，请刷新。');
   nextProfile=items;
   nextRelations=[];
   if(page==='profile'&&profileCatalog.schema_version>=2){let offset=0,total=null;do{const part=await api('profile.relation.list',{limit:100,offset},nextContext);if(total!==null&&part.total!==total)throw Error('资料关联在读取时发生变化，请刷新。');total=part.total;nextRelations.push(...part.items);offset=part.next_offset;}while(offset!==null);if(new Set(nextRelations.map(r=>r.id)).size!==total)throw Error('资料关联分页不完整，请刷新。');}
  }
  let nextIntention=intentionRead,nextResumes=resumeRecords,nextAnswers=companyAnswers,nextDecisions=companyDecisions;
  if(page==='intention'){intentionCatalog=intentionCatalog||await api('intention.schema',{},nextContext);nextIntention=await api('intention.get',{},nextContext);nextDecisions=await readRecordPages('decision.list',nextContext);}
  if(page==='resumes')nextResumes=await readRecordPages('resume.list',nextContext);
  if(page==='intention'||page==='resumes')nextAnswers=await readRecordPages('answer.list',nextContext);
  let nextTasks={items:taskRecords,total:taskTotal};
  if(page==='tasks')nextTasks=await api('task.list',{limit:50,offset:taskOffset,status:taskStatus||undefined},nextContext);
  if($('#account-select')){
   const result=await fetch('/api/accounts');const payload=await result.json();ensureAccount(context);
   if(!result.ok||!payload.ok)throw Error(payload.error?.message||'读取本地账号失败');accounts=payload.data.items||[];
  }
  if(version!==loadVersion)return false;
  profileRead=nextProfile;profileRelations=nextRelations;intentionRead=nextIntention;resumeRecords=nextResumes;companyAnswers=nextAnswers;companyDecisions=nextDecisions;state=nextState;applicationLoadInfo=nextCoverage;resources=nextResources;taskRecords=nextTasks.items||[];taskTotal=nextTasks.total||0;renderAccounts();
  $('#save-state').textContent='已读取 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});
  await render();return version===loadVersion;
 }catch(e){
  if(version===loadVersion&&recoverAccount&&['account_changed','account_context_required'].includes(e.code)){
   ++accountEpoch;clearAccountView();renderAccounts();const loaded=await load(false);if(loaded)notify('其他页面已切换账号，已读取当前账号的数据库资料。');return loaded;
  }
  if(version===loadVersion&&!staleAccount(e))notify(e.message,true);return false;
 }
}
function renderAccounts(){const select=$('#account-select');if(!select)return;const id=accountContext().userId;select.innerHTML=accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)}</option>`).join('');select.disabled=accountSwitching||!accounts.length;$('#account-new').disabled=accountSwitching||!id;select.title=state.account?`本地账号 ID：${state.account.id}`:'本地用户资料分区';}
function clearAccountView(){
 if(typeof CareerForms!=='undefined')CareerForms.reset();
 ++loadVersion;++renderVersion;state={records:{},documents:[],settings:{}};resources=[];editing=null;taskEditing=null;otpState=null;otpBusy=false;publicRegistry=null;registryBusy=false;
 profileRead=null;profileRelations=[];intentionRead=null;resumeRecords=[];companyAnswers=[];resumeEditing=null;answerEditing=null;composeRead=null;companyDecisions=[];decisionEditing=null;profileTab='basic';query='';stageFilter='';progressFilter='open';companyFilter='';collapsedCompanies.clear();recommendQuery='';recommendType='campus';recommendCompany='';recommendCity='';collapsedRecommendationCompanies.clear();preparingRecommendations.clear();recommendationExclusionEdit=null;recommendationExclusionBusy=false;++recommendationExclusionView;taskRecords=[];taskTotal=0;taskOffset=0;taskStatus='';applicationLoadInfo={complete:true,expected:0};
 $$('dialog').forEach(dialog=>{if(dialog.open)dialog.close();});$('#notice').hidden=true;$('#toast').hidden=true;$('#content').innerHTML=empty('正在切换账号','正在读取所选账号的数据库资料…');$('#save-state').textContent='';
}
async function switchAccount(id,fromCreate=false){
 if(accountSwitching)return false;const source=accountContext();if(id===source.userId&&!fromCreate)return true;
 accountSwitching=true;++accountEpoch;const context={...source,epoch:accountEpoch};clearAccountView();renderAccounts();
 try{await api('account.select',{id},context);accountSwitching=false;const loaded=await load();if(loaded)notify('已切换本地账号');return loaded;}
 catch(error){accountSwitching=false;renderAccounts();notify(error.message,true);await load();return false;}
}
async function createAccount(event){
 event.preventDefault();const context=accountContext(),button=event.target.querySelector('[type=submit]'),name=String(new FormData(event.target).get('name')||'').trim();if(!name)return;
 button.disabled=true;try{const account=await api('account.create',{name},context);ensureAccount(context);event.target.reset();$('#account-editor').close();await switchAccount(account.id||account.account?.id,true);}catch(error){if(!staleAccount(error))notify(error.message,true);}finally{button.disabled=false;}
}
function rows(kind){return state.records?.[kind]||[]}
function titleOf(r){const d=r.data||{};return d.name||d.title||d.school||d.relation||d.value||labels[r.kind]||'资料'}
function badge(text,type=''){return `<span class="badge ${type}">${esc(text)}</span>`}
function when(v){if(!v)return '尚未核验';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function empty(title,text,button=''){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`}
function editButton(kind,id='',text='编辑'){return `<button class="button secondary small" data-edit="${esc(kind)}" data-id="${esc(id)}">${text}</button>`}
function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
function link(v,label='查看官网'){const u=safeUrl(v);return u?`<a href="${esc(u)}" target="_blank" rel="noreferrer noopener">${esc(label)}</a>`:''}
async function render(){
 const version=++renderVersion;
 document.title=`${titles[page]} · Career`;$('#page-title').textContent=titles[page];
 $$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 const body=$('#content');
 if(page==='overview')body.innerHTML=overview();
 if(page==='profile')body.innerHTML=profile();
 if(page==='intention')body.innerHTML=intentionPage();
 if(page==='resumes')body.innerHTML=resumesPage();
 if(page==='recommendations')body.innerHTML=recommendations();
 if(page==='applications')body.innerHTML=applications();
 if(page==='documents')body.innerHTML=documents();
 if(page==='forms'&&typeof CareerForms!=='undefined')body.innerHTML=CareerForms.render();
 if(page==='tasks')body.innerHTML=tasks();
 if(page==='resources')body.innerHTML=resourcePage();
 if(page==='settings'){otpState=null;otpBusy=false;syncState=null;syncBusy=false;body.innerHTML=settings();}
 bind();
 if(page==='forms'&&typeof CareerForms!=='undefined')CareerForms.bind();
 if(page==='settings'){
  await Promise.all([
   (async()=>{try{const status=await api('otp.status');if(version===renderVersion)applyOtpStatus(status);}catch(error){if(version===renderVersion)$('#otp-status').textContent='读取验证码配置失败，请刷新后重试：'+otpError(error);}})(),
   (async()=>{try{const status=await api('sync.status');if(version===renderVersion)applySyncStatus(status,true);}catch(error){if(version===renderVersion)$('#sync-status').textContent='读取同步配置失败：'+error.message;}})()
  ]);
  pollSyncStatus(version);
 }
}
function applicationRecords(){return rows('application').filter(r=>!isRecommendation(r.data))}
function recommendationRecords(){return rows('application').filter(r=>isRecommendation(r.data))}
function applicationCoverageNotice(){return applicationLoadInfo.complete?'':`<div class="record-load-warning" role="alert">投递与推荐记录未全部读取：当前 ${rows('application').length} / ${applicationLoadInfo.expected} 条。以下数量仅代表已读取记录，请刷新后再核对；未读到的岗位不代表不存在。</div>`}
function recruitmentType(data){
 const text=[data.title,data.program].filter(Boolean).join(' ');
 if(/实习|\bintern(?:ship)?s?\b/i.test(text))return 'internship';
 if(/校招|校园招聘|应届|秋招|春招|\bcampus\b|\bgraduate recruitment\b|\bgraduate program\b/i.test(text))return 'campus';
 if(/社招|社会招聘|\bexperienced hire\b/i.test(text))return 'experienced';
 return 'unknown';
}
const recruitmentTypeNames={campus:'正式校招',internship:'历史实习候选',experienced:'社会招聘',unknown:'招聘类型待确认'};
const recommendationBuckets={recommended:'可推荐',exploratory:'探索项',pending:'待核验',excluded:'不推荐'};
const recommendationTiers={A:'A · 直接匹配',B:'B · 迁移匹配',C:'C · 探索匹配'};
function recommendationBucket(data){return ['candidate','preparing','profile_saved'].includes(data.stage)&&Object.hasOwn(recommendationBuckets,data.recommendation_bucket)?data.recommendation_bucket:'pending'}
function recommendationTier(data){return Object.hasOwn(recommendationTiers,data.fit_tier)?data.fit_tier:null}
function compareText(a,b){return String(a??'').localeCompare(String(b??''),'zh-CN')}
function compareRecommendationTier(a,b){return ['A','B','C',null].indexOf(recommendationTier(a.data))-['A','B','C',null].indexOf(recommendationTier(b.data))}
function recommendationIdentity(record){const d=record.data;return [d.program,d.job_id||safeUrl(d.url)||d.title,record.id]}
function compareRecommendations(a,b){
 const tier=compareRecommendationTier(a,b);if(tier)return tier;
 const left=recommendationIdentity(a),right=recommendationIdentity(b);
 for(let i=0;i<left.length;i++){const order=compareText(left[i],right[i]);if(order)return order}return 0;
}
function recommendationSections(list){
 return Object.keys(recommendationBuckets).map(bucket=>{
  const groups=groupCompanies(list.filter(r=>recommendationBucket(r.data)===bucket));
  for(const items of groups.values())items.sort(compareRecommendations);
  return {bucket,groups:new Map([...groups].sort(([a,left],[b,right])=>compareRecommendationTier(left[0],right[0])||compareText(a,b)))};
 }).filter(section=>section.groups.size);
}
function groupCompanies(list){const groups=new Map();for(const r of list){const name=r.data.company||'公司待确认';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(r)}return groups}
function companyNames(list){return [...new Set(list.map(r=>r.data.company||'公司待确认'))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function recordCities(value){return value?String(value).split(/[/／、,，;；|\s]+/).filter(Boolean):['城市待确认']}

function groupedJobTables(groups,{collapsed,tableClass,head,row,summary,groupAttribute='data-company-group',groupKey=name=>name}){
 return [...groups].map(([name,items])=>`<details class="company-group" ${groupAttribute}="${esc(groupKey(name))}" ${collapsed.has(groupKey(name))?'':'open'}><summary><strong>${esc(name)}</strong><span>${esc(summary(items))}</span></summary><div class="panel table-wrap"><table class="${tableClass}"><thead><tr>${head.map(text=>`<th>${esc(text)}</th>`).join('')}</tr></thead><tbody>${items.map(row).join('')}</tbody></table></div></details>`).join('');
}
function overview(){
 const all=Object.values(state.records||{}).flat(),apps=applicationRecords(),candidates=recommendationRecords().filter(r=>recruitmentType(r.data)==='campus'),profileRecords=all.filter(r=>!['application','preference','company_answer','resume_variant','company_decision'].includes(r.kind)),unconfirmed=profileRecords.filter(r=>r.status==='unconfirmed'||r.status==='unknown').length,basic=rows('basic')[0];
 return `${applicationCoverageNotice()}<div class="summary-grid"><div class="stat"><div class="label">投递记录</div><div class="number">${apps.length}</div><div class="hint">仅统计实际投递，含已结束历史</div></div><div class="stat"><div class="label">正式校招推荐</div><div class="number">${candidates.length}</div><button class="button ghost small" data-go="recommendations">查看推荐岗位</button></div><div class="stat"><div class="label">经历与资料</div><div class="number">${profileRecords.length}</div><div class="hint">可用于后续准备</div></div><div class="stat"><div class="label">简历材料</div><div class="number">${state.documents?.length||0}</div><div class="hint">原始材料与有效交付</div></div></div><div class="columns"><section class="panel"><div class="section-header"><h2>最近的申请记录</h2><button class="button ghost" data-go="applications">查看全部</button></div>${apps.length?apps.slice(0,5).map(r=>`<div class="list-line"><div class="record-top"><strong>${esc(r.data.company)} · ${esc(r.data.title)}</strong>${badge(stageNames[r.data.stage]||r.data.stage||'待核验','blue')}</div><p>${esc(r.data.city||'城市待确认')}　${esc(r.data.raw_status||'暂无官网原始状态')}</p></div>`).join(''):empty('还没有申请记录','可以在推荐岗位中选择岗位并开始准备，或让 Codex 读取已有投递。','<button class="button secondary small" data-go="recommendations">查看推荐岗位</button>')}</section><section class="panel"><div class="section-header"><h2>我的资料</h2><button class="button ghost" data-go="profile">查看资料</button></div>${basic?`<p class="profile-name">${esc(basic.data.name||'我的档案')}</p><p class="muted">${esc(basic.data.location||'所在地待补充')}</p><p class="record-summary">${esc(basic.data.summary||'从已经确认的经历开始准备。')}</p>`:empty('建立个人档案','导入本地简历供 Codex 整理，或直接手工补充。',editButton('basic','','填写资料'))}${unconfirmed?`<div class="pending-count">有 ${unconfirmed} 条资料待确认，可在个人资料中逐项查看。</div>`:''}</section></div><section class="panel"><div class="section-header"><h2>最近修改</h2><button class="button ghost" id="show-history">查看变更记录</button></div><p class="muted">资料来源、用户修正与公司专用信息分别保留。可以查看历史并撤销最近的修改。</p></section>`;
}
function profileSection(){return profileTab==='uncategorized'?{id:'uncategorized',kind:'experience',label:'未分类经历'}:profileCatalog?.sections.find(s=>s.id===profileTab)||{id:'basic',kind:'basic',label:'基础信息'}}
function sectionRows(section){const list=profileRead||Object.values(state.records).flat();return list.filter(r=>r.kind===section.kind&&(!section.category||r.data?.category===section.category))}
function profile(){
 if(!profileCatalog)return empty('资料字段尚未读取','请刷新后再编辑。');
 const sections=[...profileCatalog.sections,{id:'uncategorized',kind:'experience',label:'未分类经历'}],section=profileSection();
 const unclassified=(profileRead||[]).filter(r=>r.kind==='experience'&&!profileCatalog.sections.some(s=>s.kind==='experience'&&s.category===r.data?.category));
 const list=profileTab==='uncategorized'?unclassified:sectionRows(section),legacy=section.legacy;
 return `<div class="tabs">${sections.filter(s=>s.id!=='uncategorized'||unclassified.length).map(s=>`<button data-tab="${s.id}" class="${profileTab===s.id?'active':''}">${esc(s.label)} <span class="muted">${s.id==='uncategorized'?unclassified.length:sectionRows(s).length}</span></button>`).join('')}</div><div class="section-header"><div><h2>${esc(profileTab==='uncategorized'?'未分类经历':section.label)}</h2><p>${legacy?'旧记录保留来源。意向在“求职意向”统一编辑；公司例外、历史约束仍需迁移核对。':esc(section.help||'每条资料保留身份、来源与修改历史；项目、论文、研究分别维护。')}</p></div>${legacy?'':editButton(section.kind,'','新增'+section.label)}</div><div class="plain-actions spaced"><button class="button secondary" id="profile-preview">查看字段整理预览</button><button class="button ghost" data-go="intention">编辑求职意向</button></div>${list.length?`<div class="card-grid">${list.map(r=>legacy?legacyCard(r):recordCard(r)).join('')}</div>`:empty(section.id==='family'?'无任职情况（默认）':'暂无'+section.label,section.id==='family'?'存在亲属任职信息时再新增，填写一次后按公司范围判断。':'可以手工新增或由 Agent 整理。')}<div class="plain-actions spaced"><button class="button secondary" id="export-profile">导出结构化 JSON</button><button class="button ghost" id="import-profile">导入档案 JSON</button><input type="file" id="profile-file" class="hidden-file" accept=".json"></div>`
}
function legacyCard(r){return `<article class="record-card"><h3>${esc(r.data.notes||'待整理记录')}</h3><p>${esc(String(r.data.value??'').slice(0,160))}</p><div class="record-meta"><span>${esc(r.scope)}</span><button class="button ghost small" data-legacy-view="${esc(r.id)}">查看原文与来源</button><button class="button ghost small" data-history="${esc(r.id)}">修改历史</button></div></article>`}
async function readRecordPages(operation,context){let offset=0,total=null,items=[];do{const part=await api(operation,{limit:100,offset},context);if(!Array.isArray(part.items)||!Number.isInteger(part.total)||total!==null&&part.total!==total)throw Error('记录在读取时发生变化，请刷新。');total=part.total;if(part.next_offset!==null&&(!part.items.length||part.next_offset<=offset))throw Error('记录分页不完整，请刷新。');items.push(...part.items);offset=part.next_offset;}while(offset!==null);if(new Set(items.map(r=>r.id)).size!==total)throw Error('记录分页不完整，请刷新。');return items;}
function intentionPage(){return `<div class="settings-grid">${preferenceSettings()}${(intentionRead?.legacy_count??rows('preference').length)>0?`<section class="panel"><h2>旧偏好整理</h2><p>当前意向只有一份。核对旧偏好中的城市梯队、薪资和公司答案后，再应用可明确归类的内容。</p><button class="button secondary" id="legacy-preview">核对旧偏好</button><button class="button ghost" data-go="profile">查看个人资料</button><p class="help">待核对旧记录：${esc(intentionRead?.legacy_count??rows('preference').length)} 条</p></section>`:''}${companyDecisionsPanel()}${companyAnswersPanel()}</div>`}
const resumeSections=[['summary','个人简介'],['education','教育经历'],['projects','项目'],['research','研究'],['publications','论文'],['employment','工作／实习'],['skills','技能']];
const resumeSelections=[['project_ids','项目','project'],['research_ids','研究','research'],['publication_ids','论文','publication'],['employment_ids','工作／实习','work'],['skill_ids','技能','skill']];
function resumesPage(){return `<div class="section-header"><div><h2>简历方案</h2><p>选择资料和展示顺序，为目标岗位保存一份简历文案。基础信息与教育经历引用当前个人资料。</p></div><button class="button" id="resume-new">新建方案</button></div>${resumeRecords.length?`<div class="card-grid">${resumeRecords.map(r=>`<article class="record-card"><div class="record-top"><h3>${esc(r.data.name)}</h3>${badge(statusNames[r.status]||'待确认',r.status==='confirmed'?'good':'warning')}</div><p class="record-summary">${esc(resumeSummaryLabel(r))}</p><p class="help">${resumeSelections.map(([key,label])=>`${label} ${(r.data[key]||[]).length}`).join(' · ')}${r.data.target_scope?`<br>适用范围：${esc(r.data.target_scope)}`:''}</p><div class="plain-actions"><button class="button secondary small" data-resume-edit="${esc(r.id)}">编辑方案</button><button class="button small" data-resume-compose="${esc(r.id)}">预览与导出</button></div><details class="profile-provenance"><summary>来源与历史</summary><p>来源：${esc(r.source||'未标注')} · 范围：${esc(r.scope||'global')}</p><button class="button ghost small" data-history="${esc(r.id)}">修改记录</button><button class="button ghost small" data-resume-archive="${esc(r.id)}">归档方案</button></details></article>`).join('')}</div>`:empty('暂无简历方案','先选择项目、研究与论文，再按岗位调整文案。')}${companyAnswersPanel()}`;}
function companyOptions(){return `<datalist id="company-options">${resources.map(r=>`<option value="${esc(r.name||r.id)}"></option>`).join('')}<option value="京东"></option><option value="快手"></option></datalist>`;}
function companyName(id){return resources.find(r=>r.id===id)?.name||({kuaishou:'快手'})[id]||id;}
function resolveCompanyId(value,originalId='',originalName=''){const text=String(value||'').trim();if(originalId&&[originalId,originalName,companyName(originalId)].includes(text))return originalId;const known=resources.find(r=>r.id===text||r.name===text);return known?.id||({'京东':'jd','快手':'kuaishou'})[text]||text;}
function recruitmentScopeLabel(scope){if(scope==='general')return '通用';const window=String(scope||'').match(/^campus_graduation_window_(\d{4})-(\d{2})$/);if(window)return `毕业窗口自${window[1]}年${Number(window[2])}月起的校招`;const job=String(scope||'').match(/^submitted_job:(.+)$/);return job?`已投岗位 ${job[1]}`:scope||'';}
function readRecruitmentScope(value,original=''){const text=String(value||'').trim();if(text===recruitmentScopeLabel(original))return original;if(text==='通用')return 'general';return companyAnswers.map(r=>r.data.recruitment_scope).find(scope=>recruitmentScopeLabel(scope)===text)||text;}
function resumeSummaryLabel(record){if(record.data.summary_text===null||record.data.summary_text===undefined){const basic=(profileRead||[]).find(r=>r.kind==='basic')||rows('basic')[0];return basic?.data.summary?'沿用个人资料简介':'尚未填写个人简介';}return record.data.summary_text||'此方案不显示个人简介';}
const companyDecisionNames={pause:'暂停推进',exclude:'排除',watch:'恢复评估'};
function companyDecisionsPanel(){return `<section class="panel company-decisions"><div class="section-header"><div><h2>公司决定</h2><p>记录对某家公司的当前决定，修改后以最新决定继续求职。</p></div><button class="button secondary" id="decision-new">新增决定</button></div>${companyDecisions.length?companyDecisions.map(r=>`<article class="list-line"><div class="record-top"><h3>${esc(r.data.company_name||companyName(r.data.company_id))}</h3>${badge(companyDecisionNames[r.data.decision]||'待核对',r.data.decision==='pause'?'warning':r.data.decision==='watch'?'blue':'')}</div><p class="answer-value">${esc(r.data.reason||'尚未填写原因')}</p><div class="plain-actions"><button class="button secondary small" data-decision-edit="${esc(r.id)}">修改决定</button><button class="button ghost small" data-history="${esc(r.id)}">修改记录</button><button class="button ghost small" data-decision-archive="${esc(r.id)}">归档</button></div></article>`).join(''):'<p class="muted">暂无公司决定。可以记录暂停推进、排除或恢复评估的公司。</p>'}</section>`;}
async function openDecision(id='',context=accountContext()){const view=renderVersion,record=id?await api('decision.get',{id},context):null;ensureAccount(context);if(view!==renderVersion||page!=='intention')return;decisionEditing={record,context};const data=record?.data||{};showDetail(id?'修改公司决定':'新增公司决定',`<form id="decision-form"><label>公司<input name="company_name" required maxlength="500" list="decision-company-options" value="${esc(data.company_name||companyName(data.company_id)||'')}" placeholder="选择或填写公司名称"><datalist id="decision-company-options">${resources.map(r=>`<option value="${esc(r.name||r.id)}"></option>`).join('')}</datalist></label><label>当前决定<select name="decision">${Object.entries(companyDecisionNames).map(([key,label])=>`<option value="${key}" ${(data.decision||'pause')===key?'selected':''}>${label}</option>`).join('')}</select></label><label>原因<textarea name="reason" rows="4" maxlength="12000">${esc(data.reason||'')}</textarea></label><p class="help">公司决定由本人维护，Agent 执行求职任务时读取最新决定。</p><div class="form-actions"><button type="button" class="button secondary" id="decision-cancel">取消</button><button type="submit" class="button" id="decision-save">保存决定</button></div></form>`);$('#decision-cancel').onclick=()=>$('#detail').close();$('#decision-form').onsubmit=saveDecision;}
async function saveDecision(event){event.preventDefault();const editor=decisionEditing,form=event.target;if(!editor||editor.busy||!form.reportValidity())return;editor.busy=true;const button=$('#decision-save');button.disabled=true;try{ensureAccount(editor.context);const values=new FormData(form),name=String(values.get('company_name')||'').trim(),current=editor.record?.data||{},companyId=resolveCompanyId(name,current.company_id,current.company_name),candidate={company_id:companyId,company_name:name,decision:values.get('decision'),reason:String(values.get('reason')||'')},data={};for(const [key,value]of Object.entries(candidate))if(!editor.record||JSON.stringify(value)!==JSON.stringify(current[key]))data[key]=value;const args={data};if(editor.record)Object.assign(args,{id:editor.record.id,revision:editor.record.revision});await api('decision.save',args,editor.context);ensureAccount(editor.context);decisionEditing=null;$('#detail').close();notify('公司决定已保存');await load();}catch(error){if(!staleAccount(error))notify(error.message,true);}finally{editor.busy=false;button.disabled=false;}}
async function archiveDecision(id,context=accountContext()){const row=companyDecisions.find(r=>r.id===id);if(!row)return;showDetail('归档公司决定',`<p>将归档 ${esc(row.data.company_name||companyName(row.data.company_id))} 的当前决定，原文保留在修改历史中。</p>`,'<button class="button secondary" id="decision-archive-cancel">取消</button><button class="button danger" id="decision-archive-confirm">确认归档</button>');$('#decision-archive-cancel').onclick=()=>$('#detail').close();$('#decision-archive-confirm').onclick=async()=>{const button=$('#decision-archive-confirm');button.disabled=true;try{await api('decision.archive',{id,revision:row.revision},context);ensureAccount(context);$('#detail').close();notify('公司决定已归档');await load();}catch(error){if(!staleAccount(error))notify(error.message,true);}finally{button.disabled=false;}};}
function companyAnswersPanel(){return `<section class="panel company-answers"><div class="section-header"><div><h2>公司填写答案</h2><p>保存特定公司的表单答案，填写时按公司和有效期取用。</p></div><button class="button secondary" id="answer-new">新增答案</button></div>${companyAnswers.length?`<div class="answer-list">${companyAnswers.map(r=>`<article class="list-line"><div class="record-top"><h3>${esc(r.data.label||r.data.question_key)}</h3>${badge(statusNames[r.status]||'待确认',r.status==='confirmed'?'good':'warning')}</div><p>${esc(companyName(r.data.company_id))}${r.data.recruitment_scope?` · ${esc(recruitmentScopeLabel(r.data.recruitment_scope))}`:''}${r.data.expires_at?` · 有效期至 ${esc(r.data.expires_at)}`:''}</p><p class="answer-value">${esc(profileValue(r.data.value))}</p><div class="plain-actions"><button class="button secondary small" data-answer-edit="${esc(r.id)}">编辑答案</button><button class="button ghost small" data-history="${esc(r.id)}">修改记录</button><button class="button ghost small" data-answer-archive="${esc(r.id)}">归档</button></div></article>`).join('')}</div>`:'<p class="muted">暂无公司答案。家庭任职信息未填写时默认无任职，无需逐公司新增“无”。</p>'}</section>`;}
function editorSourceRows(editor){return [...new Map([...(profileRead||[]),...(editor?.record?.source_review?.current_sources||[])].map(row=>[row.id,row])).values()];}
function editorSourceVersions(editor,ids){const byId=new Map(editorSourceRows(editor).map(row=>[row.id,row]));return Object.fromEntries([...new Set(ids)].map(id=>byId.get(id)).filter(row=>row&&Number.isInteger(row.revision)&&row.revision>0).map(row=>[row.id,row.revision]));}
function resumeSelectionRows(key,category){const selected=resumeEditing?.data[key]||[],available=editorSourceRows(resumeEditing).filter(r=>r.kind==='experience'&&r.data.category===category),byId=new Map(available.map(r=>[r.id,r]));return [...selected.map(id=>byId.get(id)||{id,data:{title:'原条目不可用（保留引用）'},missing:true}),...available.filter(r=>!selected.includes(r.id))];}
function resumePickers(){return resumeSelections.map(([key,label,category])=>`<fieldset class="resume-picker"><legend>${label}</legend>${resumeSelectionRows(key,category).map(r=>{const selected=(resumeEditing.data[key]||[]).includes(r.id),index=(resumeEditing.data[key]||[]).indexOf(r.id);return `<div class="resume-choice"><label class="check"><input type="checkbox" data-resume-pick="${esc(key)}" data-record-id="${esc(r.id)}" ${selected?'checked':''}><span>${esc(titleOf(r))}${r.missing?'':`<small>${esc(statusNames[r.status]||'待确认')}</small>`}</span></label>${selected?`<div class="plain-actions"><button type="button" class="button ghost small" data-resume-move="${esc(key)}" data-record-id="${esc(r.id)}" data-direction="-1" ${index===0?'disabled':''} aria-label="上移${esc(titleOf(r))}">↑</button><button type="button" class="button ghost small" data-resume-move="${esc(key)}" data-record-id="${esc(r.id)}" data-direction="1" ${index===resumeEditing.data[key].length-1?'disabled':''} aria-label="下移${esc(titleOf(r))}">↓</button></div>`:''}</div>`;}).join('')||'<p class="help">尚无可选择的资料</p>'}</fieldset>`).join('');}
function resumeOrderHtml(){return (resumeEditing.data.section_order||resumeSections.map(([key])=>key)).map((key,index)=>`<div class="resume-choice"><span>${esc(resumeSections.find(s=>s[0]===key)?.[1]||key)}</span><div class="plain-actions"><button type="button" class="button ghost small" data-section-move="${esc(key)}" data-direction="-1" ${index===0?'disabled':''} aria-label="上移章节">↑</button><button type="button" class="button ghost small" data-section-move="${esc(key)}" data-direction="1" ${index===resumeEditing.data.section_order.length-1?'disabled':''} aria-label="下移章节">↓</button></div></div>`).join('');}
function resumeOverrideHtml(){const ids=resumeSelections.flatMap(([key])=>resumeEditing.data[key]||[]),overrides=resumeEditing.data.text_overrides||{};return ids.map(id=>{const row=editorSourceRows(resumeEditing).find(r=>r.id===id);if(!row)return '';const keys=['description','responsibilities','results','abstract'].filter(key=>row.data[key]!==undefined||overrides[id]?.[key]!==undefined);if(!keys.length)return '';return `<details class="source-fields"><summary>${esc(titleOf(row))}：方案中的文案</summary>${keys.map(key=>{const custom=Object.hasOwn(overrides[id]||{},key);return `<div class="resume-override"><label class="check"><input type="checkbox" data-override-use="${esc(id)}" data-field="${key}" ${custom?'checked':''}>单独调整${esc(profileFieldLabel(key))}</label><textarea data-override-text="${esc(id)}" data-field="${key}" rows="5" ${custom?'':'disabled'}>${esc(custom?overrides[id][key]:row.data[key]||'')}</textarea>${custom?`<details class="profile-provenance"><summary>当前资料原文</summary><p class="resume-source-text">${esc(row.data[key]||'尚无该字段原文')}</p></details>`:''}</div>`;}).join('')}</details>`;}).join('')||'<p class="help">选择条目后，可单独调整方案文案。个人资料原文继续保留。</p>';}
async function openResume(id='',context=accountContext()){const view=renderVersion,record=id?await api('resume.get',{id},context):null;ensureAccount(context);if(view!==renderVersion||page!=='resumes')return;const data=structuredClone(record?.data||{});for(const [key]of resumeSelections)data[key]=data[key]||[];data.section_order=data.section_order||resumeSections.map(([key])=>key);data.text_overrides=data.text_overrides||{};delete data.source_fingerprints;resumeEditing={record,data,context,initialData:structuredClone(data)};showDetail(id?'编辑简历方案':'新建简历方案',`<form id="resume-form"><label>方案名称<input name="name" required maxlength="200" value="${esc(data.name||'')}" placeholder="例如：算法研究岗位"></label><label class="check"><input name="use_basic_summary" id="resume-use-basic-summary" type="checkbox" ${data.summary_text===null||data.summary_text===undefined?'checked':''}>引用个人资料中的简介</label><label>方案中的个人简介<textarea name="summary_text" rows="4" maxlength="12000" ${data.summary_text===null||data.summary_text===undefined?'disabled':''}>${esc(data.summary_text??(profileRead||[]).find(r=>r.kind==='basic')?.data.summary??'')}</textarea></label><div class="form-grid"><label>适用岗位或范围<input name="target_scope" value="${esc(data.target_scope||'')}"></label><label>确认状态<select name="status">${[...new Set(['unconfirmed','confirmed',record?.status])].filter(Boolean).map(k=>`<option value="${k}" ${(record?.status||'unconfirmed')===k?'selected':''}>${statusNames[k]}</option>`).join('')}</select></label></div>${resumeSourceReviewHtml(record)}<h3>选择简历条目</h3><p class="help">勾选后用上下箭头调整顺序。项目与论文分别选择，关联资料不会自动加入。</p><div id="resume-pickers">${resumePickers()}</div><details class="source-fields"><summary>章节顺序</summary><div id="resume-order">${resumeOrderHtml()}</div></details><details class="source-fields"><summary>按方案调整文案</summary><div id="resume-overrides">${resumeOverrideHtml()}</div></details><div class="form-actions"><button type="button" id="resume-cancel" class="button secondary">取消</button><button type="submit" id="resume-save" class="button">保存方案</button></div></form>`);$('#resume-cancel').onclick=()=>$('#detail').close();$('#resume-form').onsubmit=saveResume;$('#resume-use-basic-summary').onchange=event=>{$('#resume-form').querySelector('[name=summary_text]').disabled=event.target.checked;};bindResumeEditor();}
function moveSelected(list,id,direction){const index=list.indexOf(id),next=index+direction;if(index<0||next<0||next>=list.length)return;[list[index],list[next]]=[list[next],list[index]];}
function bindResumeEditor(){const editor=resumeEditing;$$('[data-resume-pick]').forEach(input=>input.onchange=()=>{ensureAccount(editor.context);const list=editor.data[input.dataset.resumePick],id=input.dataset.recordId;if(input.checked){if(!list.includes(id))list.push(id);}else{editor.data[input.dataset.resumePick]=list.filter(value=>value!==id);if(!resumeSelections.some(([key])=>editor.data[key].includes(id)))delete editor.data.text_overrides[id];}refreshResumeEditor();});$$('[data-resume-move]').forEach(button=>button.onclick=()=>{ensureAccount(editor.context);moveSelected(editor.data[button.dataset.resumeMove],button.dataset.recordId,Number(button.dataset.direction));refreshResumeEditor();});$$('[data-section-move]').forEach(button=>button.onclick=()=>{ensureAccount(editor.context);moveSelected(editor.data.section_order,button.dataset.sectionMove,Number(button.dataset.direction));refreshResumeEditor();});$$('[data-override-use]').forEach(input=>input.onchange=()=>{ensureAccount(editor.context);const id=input.dataset.overrideUse,key=input.dataset.field,area=$$('[data-override-text]').find(a=>a.dataset.overrideText===id&&a.dataset.field===key);editor.data.text_overrides[id]=editor.data.text_overrides[id]||{};if(input.checked)editor.data.text_overrides[id][key]=area.value;else{delete editor.data.text_overrides[id][key];if(!Object.keys(editor.data.text_overrides[id]).length)delete editor.data.text_overrides[id];}area.disabled=!input.checked;});$$('[data-override-text]').forEach(area=>area.oninput=()=>{ensureAccount(editor.context);editor.data.text_overrides[area.dataset.overrideText]=editor.data.text_overrides[area.dataset.overrideText]||{};editor.data.text_overrides[area.dataset.overrideText][area.dataset.field]=area.value;});}
