function resumeMarkdown(result){const lines=[];for(const section of result.sections||[]){lines.push(`## ${section.label}`,'');for(const item of section.items){lines.push(`### ${item.title||titleOf(item)}`,'');for(const [key,value]of Object.entries(item.data||{})){if(value===null||value===''||value===undefined||['category','title','school','name'].includes(key))continue;lines.push(`${profileFieldLabel(key)}：${profileValue(value)}`,'');}}}return lines.join('\n');}
