function profileDefinition(kind,data={}){return (profileCatalog?.records[kind]?.fields||fields[kind].map(([key,label,type,options])=>({key,label,type,options}))).filter(f=>!f.categories||f.categories.includes(data.category));}
function hasValue(value){return value!==null&&value!==undefined&&value!==''&&(!Array.isArray(value)||value.length>0);}
function profileValue(value,definition={}){if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.join('、');if(value&&typeof value==='object')return Object.values(value).filter(hasValue).map(v=>profileValue(v)).join('；');return definition.options?.[value]||String(value??'');}
function bibliographyReady(data){return data.category==='publication'&&['venue','authors','year','doi','publication_type'].some(k=>hasValue(data[k]));}
function advancedProfileField(field,data){return field.legacy||field.hidden_categories?.includes(data.category)&&(field.key!=='description'||bibliographyReady(data));}
function visibleProfileDefinition(kind,data){return profileDefinition(kind,data).filter(f=>!advancedProfileField(f,data));}
function profileFieldLabel(key){for(const definition of Object.values(profileCatalog?.records||{})){const field=definition.fields.find(f=>f.key===key);if(field)return field.label;}return profileCatalog?.migration_labels?.[key]||key;}
function migrationCard(item,confirm=false){const changes=confirm?item.changes||{}:item.proposed_fields||{},row=(profileRead||[]).find(r=>r.id===item.id||r.id===item.record_id);return `<article class="panel migration-card"><h3>${esc(row?titleOf(row):profileCatalog?.migration_targets?.[item.target]||item.target)}</h3>${item.would_change?badge('补充专属字段','blue'):badge(item.review_required?'需手工核对':'保留原值',item.review_required?'warning':'')}<dl class="profile-facts">${Object.entries(changes).map(([key,value])=>`<dt>${esc(profileFieldLabel(key))}</dt><dd>${esc(value===null?'清空旧正文，原文保留在修改历史中':profileValue(value))}</dd>`).join('')}</dl>${(item.issues||[]).map(x=>`<p class="help">${esc(x)}</p>`).join('')}<details class="profile-provenance"><summary>原文与来源</summary><p>来源：${esc(item.source||'未标注')} · 范围：${esc(item.scope||'global')}</p>${item.original_value!==undefined?`<pre>${esc(typeof item.original_value==='object'?JSON.stringify(item.original_value,null,2):item.original_value)}</pre>`:''}</details></article>`;}
