function parsedEditorData(form){const data={...editing.workingData};for(const tuple of editing.fields){const [key,label,, ,definition={}]=tuple,value=String(form.get(key)??''),original=editing.record?.data?.[key];if(editing.record&&value===editorValue(original,definition)){if(Object.hasOwn(editing.record.data,key))data[key]=original;else delete data[key];continue;}if(['recommendation_bucket','fit_tier','recommendation_scope'].includes(key)&&!Object.hasOwn(editing.record?.data||{},key)&&!value.trim())continue;if(!value.trim()){if(hasValue(data[key])||Object.hasOwn(data,key))data[key]=null;else delete data[key];continue;}if(definition.value_type==='boolean')data[key]=value==='true';else if(definition.value_type==='string_array')data[key]=value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);else if(['number','integer'].includes(definition.value_type)){const number=Number(value);if(!Number.isFinite(number)||definition.value_type==='integer'&&!Number.isInteger(number))throw Error(label+'请填写'+(definition.value_type==='integer'?'整数。':'有效数字。'));data[key]=number;}else data[key]=['decision','next_action','blocker','job_description','jd_blocker'].includes(key)?value:value.trim();}return data;}
